import java.lang.module.*;import java.nio.file.*;import java.util.*;public class ModuleCheck45{public static void main(String[]args){var finder=ModuleFinder.of(Arrays.stream(args).map(Path::of).toArray(Path[]::new));Set<String>roots=new HashSet<>();finder.findAll().forEach(m->roots.add(m.descriptor().name()));var config=ModuleLayer.boot().configuration().resolveAndBind(finder,ModuleFinder.of(),roots);var layer=ModuleLayer.boot().defineModulesWithOneLoader(config,ClassLoader.getSystemClassLoader());System.out.println("JVM_MODULE_LAYER_RESOLVED="+roots.size());}}
